xwikidoc.content:
{{velocity}}
== OA 用户数据同步 ==

(% class="xform" %)
* **数据日期**：默认同步前一天（`xwiki.oa-sync.source.<type>.date-offset-days`）
* **定时**：每天 05:00，可在「应用 → Scheduler」修改 cron
* **记录**：每种来源保留最近 10 条
* **状态说明**：SUCCESS=全部成功；PARTIAL_FAILURE=部分失败；FAILURE=整体失败（详见 errorLog）

(% id="syncActions" class="btn-group" %)
(% class="btn btn-primary" data-sync-type="employee" %)立即同步：行员(% /%)
(% /%)

#set ($records = $xwiki.searchDocuments("where doc.object(OASync.SyncRecordClass) order by doc.creationDate desc"))
#if (!$records || $records.isEmpty())
{{info}}暂无同步记录。{{/info}}
#else
{{html clean="false"}}
<table class="table table-striped table-hover">
  <thead>
    <tr><th>类型</th><th>数据日期</th><th>触发</th><th>状态</th><th>总数</th><th>成功</th><th>失败</th><th>开始时间</th><th>错误日志</th></tr>
  </thead>
  <tbody>
  #foreach ($name in $records)
    #set ($recordDoc = $xwiki.getDocument($name))
    #set ($recordObj = $recordDoc.getObject('OASync.SyncRecordClass'))
    #if ($recordObj)
    <tr>
      <td>$recordObj.getValue('syncType')</td>
      <td>$recordObj.getValue('syncDate')</td>
      <td>$recordObj.getValue('triggerType')</td>
      <td>$recordObj.getValue('status')</td>
      <td>$recordObj.getValue('totalCount')</td>
      <td>$recordObj.getValue('successCount')</td>
      <td>$recordObj.getValue('failCount')</td>
      <td>$recordObj.getValue('startTime')</td>
      <td>
      #if ("$!recordObj.getValue('errorLog')" != '')
        <details><summary>查看失败明细</summary><pre>$escapetool.html($recordObj.getValue('errorLog'))</pre></details>
      #else
        （无）
      #end
      </td>
    </tr>
    #end
  #end
  </tbody>
</table>
{{/html}}
#end

{{html clean="false"}}
<script>
require(['jquery'], function ($) {
  $('#syncActions .btn').on('click', function () {
    var type = $(this).data('sync-type');
    var btn = $(this);
    btn.prop('disabled', true);
    $.ajax({
      url: '$request.contextPath/rest/oa-sync/trigger?type=' + type,
      method: 'POST',
      dataType: 'json',
      success: function (data) {
        new XWiki.widgets.Notification(
          '[' + data.type + '] ' + data.status + ' 成功=' + data.success + ' 失败=' + data.failed,
          'done');
      },
      error: function (xhr) {
        new XWiki.widgets.Notification('触发失败：' + xhr.responseText, 'error');
      },
      complete: function () { btn.prop('disabled', false); }
    });
  });
});
</script>
{{/html}}
{{/velocity}}
